# PillarCard

**File:** `app/components/PillarCard.tsx`

## Purpose

Displays a content pillar or category with an optional 16:9 image, title, description, related article links, and a footer CTA. Use on content hubs, category pages, and collection navigation.

## Props

| Prop | Type | Default | Description |
|---|---|---|---|
| `href` | `string` | — | React Router path to the pillar page. |
| `title` | `string` | — | Pillar title. |
| `description` | `string` | — | Pillar description. |
| `heading` | `string` | — | Small label above the title. |
| `image` | `string` | — | Pillar image URL. |
| `imageAlt` | `string` | `title` | Accessible image alt text. |
| `fallbackImage` | `string` | — | Image source used if `image` fails to load. |
| `childLinks` | `ChildLink[]` | — | Related article links. |
| `maxChildren` | `number` | `3` | Maximum child links displayed. |
| `ctaLabel` | `string` | `"View all"` | Footer CTA label. |
| `ctaHref` | `string` | `href` | React Router path for the footer CTA. |
| `priority` | `boolean` | `false` | Loads the image eagerly when `true`. |
| `className` | `string` | — | Additional card classes. |

## Types

```tsx
"use client";

import { useState } from "react";
import { Link } from "react-router";

export type ChildLink = {
    title: string;
    href: string;
    description?: string;
};

type PillarCardProps = {
    href: string;
    title: string;
    description: string;
    heading?: string;
    image?: string;
    imageAlt?: string;
    fallbackImage?: string;
    childLinks?: Array<ChildLink>;
    maxChildren?: number;
    ctaLabel?: string;
    ctaHref?: string;
    priority?: boolean;
    className?: string;
};

export function PillarCard({
    href,
    title,
    description,
    heading,
    image,
    imageAlt = title,
    fallbackImage,
    childLinks,
    maxChildren = 3,
    ctaLabel = "View all",
    ctaHref = href,
    priority = false,
    className,
}: PillarCardProps) {
    const [imageSrc, setImageSrc] = useState(image);
    const visibleChildren = childLinks?.slice(0, Math.max(0, maxChildren));

    function handleImageError(): void {
        if (fallbackImage && imageSrc !== fallbackImage) setImageSrc(fallbackImage);
    }

    return (
        <article
            className={`overflow-hidden rounded-lg border border-slate-200 bg-white shadow-sm transition-shadow hover:shadow-md ${className ?? ""}`}
        >
            {imageSrc ? (
                <Link to={href} className="block aspect-video overflow-hidden">
                    <img
                        src={imageSrc}
                        alt={imageAlt}
                        loading={priority ? "eager" : "lazy"}
                        onError={handleImageError}
                        className="h-full w-full object-cover"
                    />
