    slug: string;
    ctaText?: string;
    className?: string;
    descriptionOverride?: string;
    variant?: "default" | "compact";
    authorOverride?: Author;
};

const FALLBACK_IMAGE_SRC = "/images/article-placeholder.jpg";

function formatArticleDate(value: string): string {
    try {
        return new Intl.DateTimeFormat("en-US", {
            dateStyle: "medium",
        }).format(new Date(value));
    } catch {
        return value;
    }
}

export function ArticleCardBySlug({
    slug,
    ctaText = "Read more",
    className,
    descriptionOverride,
    variant = "default",
    authorOverride,
}: ArticleCardBySlugProps): JSX.Element | null {
